import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    if n == 0:
        return

    words = []
    for i in range(1, n + 1):
        words.append(data[i].strip())

    # Selection sort
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            # Compare by length first, then lexicographically
            if len(words[j]) < len(words[min_idx]):
                min_idx = j
            elif len(words[j]) == len(words[min_idx]):
                if words[j] < words[min_idx]:
                    min_idx = j

        if min_idx != i:
            words[i], words[min_idx] = words[min_idx], words[i]

    for word in words:
        print(word)

if __name__ == "__main__":
    main()
